var top = () => topHelp(PROG, DESCRIPTION, COMMANDS, FOOTER);
function wrongUsage(message, usage, command) {
  const help = command ? `${PROG} ${command} --help` : `${PROG} --help`;
  note(`${usage}
${PROG}${command ? " " + command : ""}: error: ${message}
Run '${help}' for help.`);
  return 2;
}
async function main(argv) {
  const [name, ...rest] = argv;
  if (name === undefined) {
    print(top());
    return 2;
  }
  if (name === "-h" || name === "--help") {
    print(top());
    return 0;
  }
  if (name === "help") {
    const asked = COMMANDS.find((command) => command.name === rest[0]);
    if (rest.length && !asked)
      return wrongUsage(`there is no command named '${rest[0]}'`, topUsage(PROG));
    print(asked ? commandHelp(PROG, asked) : top());
    return 0;
  }
  const command = COMMANDS.find((item) => item.name === name);
  if (!command) {
    const choices = COMMANDS.map((item) => `'${item.name}'`).join(", ");
    return wrongUsage(`argument COMMAND: invalid choice: '${name}' (choose from ${choices})`, topUsage(PROG));
  }
  try {
    const args = parseCommand(PROG, command, rest);
    return await command.run(args);
  } catch (error) {
    if (error instanceof HelpRequested) {
      print(error.message);
      return 0;
    }
    if (error instanceof ArgumentError)
      return wrongUsage(error.message, error.usage, command.name);
    if (error instanceof UsageError) {
      note(`usage: ${error.message}`);
      return 2;
    }
    if (error instanceof Problem || error?.code) {
      note(`failed: ${reason(error)}`);
      return 1;
    }
    throw error;
  }
}

